# Sorting Algorithms Benchmark: Quicksort vs Merge Sort

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function to swap two elements in an array
void swap(int* arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

// Partition function for Quicksort
int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = low - 1;

    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            swap(arr, i, j);
        }
    }

    swap(arr, i + 1, high);
    return i + 1;
}

// Quicksort function
void quicksort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quicksort(arr, low, pi - 1);
        quicksort(arr, pi + 1, high);
    }
}

// Function to merge two sorted subarrays
void merge(int arr[], int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;

    int* left = (int*)malloc(n1 * sizeof(int));
    int* right = (int*)malloc(n2 * sizeof(int));

    for (int i = 0; i < n1; i++) {
        left[i] = arr[l + i];
    }
    for (int j = 0; j < n2; j++) {
        right[j] = arr[m + 1 + j];
    }

    int i = 0, j = 0, k = l;

    while (i < n1 && j < n2) {
        if (left[i] <= right[j]) {
            arr[k] = left[i];
            i++;
        } else {
            arr[k] = right[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        arr[k] = left[i];
        i++;
        k++;
    }

    while (j < n2) {
        arr[k] = right[j];
        j++;
        k++;
    }

    free(left);
    free(right);
}

// Merge Sort function
void mergesort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergesort(arr, l, m);
        mergesort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}

// Function to generate random array
void generateRandomArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % 10000;
    }
}

// Function to copy array
void copyArray(int src[], int dst[], int size) {
    for (int i = 0; i < size; i++) {
        dst[i] = src[i];
    }
}

// Function to measure execution time
double measureTime(int arr[], int size, void (*sortFunc)(int*, int, int)) {
    clock_t start = clock();

    // Make a copy to avoid modifying original
    int* temp = (int*)malloc(size * sizeof(int));
    copyArray(arr, temp, size);

    sortFunc(temp, 0, size - 1);

    clock_t end = clock();
    double time = (double)(end - start) / CLOCKS_PER_SEC;

    free(temp);
    return time;
}

// Function to print benchmark results in table format
void printBenchmarkTable() {
    printf("\n========================================\n");
    printf("       SORTING ALGORITHMS BENCHMARK     \n");
    printf("========================================\n");
    printf("%-15s %-15s %-15s %-15s %-15s\n", 
           "Array Size", "Quicksort (s)", "Merge Sort (s)", "Difference (s)", "Ratio (Q/M)");
    printf("%-15s %-15s %-15s %-15s %-15s\n", 
           "------------", "-------------", "--------------", "--------------", "----------");

    int sizes[] = {100, 1000, 10000};
    int numSizes = sizeof(sizes) / sizeof(sizes[0]);

    for (int i = 0; i < numSizes; i++) {
        int size = sizes[i];
        int arr1[size];
        int arr2[size];

        generateRandomArray(arr1, size);
        generateRandomArray(arr2, size);

        double quickTime = measureTime(arr1, size, quicksort);
        double mergeTime = measureTime(arr2, size, mergesort);
        double diff = quickTime - mergeTime;
        double ratio = mergeTime > 0 ? quickTime / mergeTime : 0;

        printf("%-15d %-15.6f %-15.6f %-15.6f %-15.2f\n",
               size, quickTime, mergeTime, diff, ratio);
    }

    printf("========================================\n");
}

// Function to print array (for verification)
void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

// Function to verify array is sorted
int isSorted(int arr[], int size) {
    for (int i = 1; i < size; i++) {
        if (arr[i - 1] > arr[i]) {
            return 0;
        }
    }
    return 1;
}

// Main function with benchmark harness
int main() {
    printf("Sorting Algorithms Benchmark: Quicksort vs Merge Sort\n");
    printf("=====================================================\n\n");

    // Test Case 1: Small array (100 elements)
    printf("Test Case 1: Small Array (100 elements)\n");
    int arr1[100];
    generateRandomArray(arr1, 100);
    printf("Original: ");
    printArray(arr1, 100);
    quicksort(arr1, 0, 99);
    printf("Sorted:   ");
    printArray(arr1, 100);
    printf("Verified: %s\n", isSorted(arr1, 100) ? "PASS" : "FAIL");

    // Test Case 2: Medium array (1000 elements)
    printf("\nTest Case 2: Medium Array (1000 elements)\n");
    int arr2[1000];
    generateRandomArray(arr2, 1000);
    printf("Original: ");
    printArray(arr2, 1000);
    quicksort(arr2, 0, 999);
    printf("Sorted:   ");
    printArray(arr2, 1000);
    printf("Verified: %s\n", isSorted(arr2, 1000) ? "PASS" : "FAIL");

    // Test Case 3: Large array (10000 elements)
    printf("\nTest Case 3: Large Array (10000 elements)\n");
    int arr3[10000];
    generateRandomArray(arr3, 10000);
    printf("Original: ");
    printArray(arr3, 10000);
    quicksort(arr3, 0, 9999);
    printf("Sorted:   ");
    printArray(arr3, 10000);
    printf("Verified: %s\n", isSorted(arr3, 10000) ? "PASS" : "FAIL");

    // Print benchmark comparison table
    printBenchmarkTable();

    return 0;
}
```

## Key Features of the Benchmark Harness

### 1. **Timing Mechanism**
- Uses `clock()` for accurate timing
- Measures execution time in seconds
- Properly frees allocated memory after timing

### 2. **Test Array Sizes**
- 100 elements (small)
- 1000 elements (medium)
- 10000 elements (large)

### 3. **Verification**
- Checks if arrays are properly sorted after execution
- Ensures correctness of both algorithms

### 4. **Output Format**
- Clear table with headers
- Shows execution time for each algorithm
- Calculates difference and ratio between algorithms

### 5. **Memory Management**
- Properly allocates and frees memory
- Creates copies to avoid modifying original arrays

## Compilation and Execution

```bash
gcc -o benchmark benchmark.c -O2
./benchmark
```

